META_VALUES = ["<b>", "<div>", "'<!-- x -->'", "'*'", "'-'", "'1.'", "'***'", "'#'", "'    code'",
               "'# h'", "'- a'", "'1. a'", "'> q'", "'a|b'", "'- '", "'`x`'", "'[x]: /u'",
               "'a\\n- b'", "'b\\n\\nc'", "'```\\nx\\n```'", "'```\\nx'", "'> [!NOTE]'",
               "'t\\n: d'", "'x\\n '", "|\n  # h\n  text", "'<b> x'", "'- # h'", "'> # h'",
               '"::: d\\n:::"', '"a|b\\n-|-\\nx|y"', '"<?x\\n"', '"| a |\\n|---|\\n| b |"',
               '"```\\nx\\n"', '"<div>\\nx\\n"', '"<!-- a\\n"', '["<?x\\n", "a|b\\n-|-\\nx|y"]']


def toml_string(text):
    return json.dumps(text, ensure_ascii=False)


def main():
    out = ["# CommonMark and GFM rule cases. The inputs are written for Randoc.",
           "# tools/commonmark-cases/own_cases.py writes this file.",
           "from = \"commonmark\"", "to = []", ""]
    for cid, text in CASES:
        out += ["[[case]]", f"id = \"{cid}\"", f"input = {toml_string(text)}", ""]
        if cid.startswith(("li-", "link-", "em-", "ref-")):
            out += ["[[case]]", f"id = \"{cid}-gfm\"", "from = \"gfm\"",
                    f"input = {toml_string(text)}", ""]
    for cid, text in GFM_CASES:
        out += ["[[case]]", f"id = \"{cid}\"", "from = \"gfm\"", f"input = {toml_string(text)}", ""]
        out += ["[[case]]", f"id = \"{cid}-x\"", "from = \"commonmark_x\"",
                f"input = {toml_string(text)}", ""]
    for cid, fmt, text in REVIEW_CASES:
        if fmt.startswith("cmd:"):
            name = fmt[4:]
            out += ["[[case]]", f"id = \"{cid}\"",
                    f"cmd = [\"-f\", \"commonmark_x+rebase_relative_paths\", \"-t\", \"json\", \"{name}\"]",
                    "[case.files]", f"{toml_string(name)} = {toml_string(text)}", ""]
            continue
        out += ["[[case]]", f"id = \"{cid}\"", f"from = \"{fmt}\"", f"input = {toml_string(text)}", ""]
    for index, value in enumerate(META_VALUES):
        text = f"---\na: {value}\n---\n\nbody\n"
        for fmt in ("gfm", "commonmark_x"):
            out += ["[[case]]", f"id = \"rv-meta-{index:02d}-{fmt}\"", f"from = \"{fmt}\"",
                    f"input = {toml_string(text)}", ""]
    path = Path(__file__).resolve().parents[2] / "conformance/cases/commonmark/rules.toml"
    path.write_text("\n".join(out), encoding="utf-8")


if __name__ == "__main__":
    main()
